(7303988, 1139843, 114285, '<td valign="top">You got that right!!! And madder by the minute!! 9</td>', 'You got that right!!! And madder by the minute!! 9', '2015-01-19 01:32:23.000000', NULL, 1),
(7303990, 1139803, 123833, '<td valign="top">Ton image est si beaucoup mieux que les autres, je ne vais plus voter au DPC. Désolée, Christophe. Ton image montre beaucoup de réflexion et de la capacité d''exprimer tes émotions dans l''image la plus iconique de la France. Ton image est exceptionnelle.<br/> <br/>Je suis Charlie.<br/> <br/>La culture française est ma culture, c''est mon passé et mon avenir. La solidarité avec Charlie Hebdo est très important pour moi. Mes parents avaient peur de dire quoi que ce soit contre le régime, ils ont vécu dans la peur pour leur vie. Je ne vais pas vivre dans la peur!<br/> <br/>Vive la liberté d''expression! Vive la France libre!</td>', 'Ton image est si beaucoup mieux que les autres, je ne vais plus voter au DPC. Désolée, Christophe. Ton image montre beaucoup de réflexion et de la capacité d''exprimer tes émotions dans l''image la plus iconique de la France. Ton image est exceptionnelle. Je suis Charlie. La culture française est ma culture, c''est mon passé et mon avenir. La solidarité avec Charlie Hebdo est très important pour moi. Mes parents avaient peur de dire quoi que ce soit contre le régime, ils ont vécu dans la peur pour leur vie. Je ne vais pas vivre dans la peur! Vive la liberté d''expression! Vive la France libre!', '2015-01-19 01:38:07.000000', NULL, 1),
