(7306936, 1139803, 63244, '<td valign="top">What a fantastic piece of art and a perfect statement piece!<br/>Congrats on your blue!</td>', 'What a fantastic piece of art and a perfect statement piece!Congrats on your blue!', '2015-01-26 14:56:44.000000', NULL, 0),
(7306949, 1139803, 159196, '<td valign="top">Congrats on the blue - not that I doubted it for a moment. I am astounded at your commitment, not only to your art but also to things that matter to you. I remember the days when our children were babies and how I thought that I had so little time. I look at your work, and the instrumental part your wife plays in it and wonder by what wizardry you manage to double the hours in a day to enable you to give everything your best shot.</td>', 'Congrats on the blue - not that I doubted it for a moment. I am astounded at your commitment, not only to your art but also to things that matter to you. I remember the days when our children were babies and how I thought that I had so little time. I look at your work, and the instrumental part your wife plays in it and wonder by what wizardry you manage to double the hours in a day to enable you to give everything your best shot.', '2015-01-26 16:17:25.000000', NULL, 0),
(7306950, 1139725, 159196, '<td valign="top">Congrats on such a different and superb image.</td>', 'Congrats on such a different and superb image.', '2015-01-26 16:19:25.000000', NULL, 0),
